describe('Debounced Search Functionality', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should trigger search only after user stops typing for 300ms', () => {
    // Setup: intercept the search API call
    cy.intercept('GET', '/api/search*').as('searchRequest');

    // Get the search input element
    cy.get('[data-testid="search-input"]').should('be.visible');

    // Type a query quickly
    cy.get('[data-testid="search-input"]').type('quick search');

    // Verify API call is made immediately
    cy.wait('@searchRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Type a second query to trigger another API call
    cy.get('[data-testid="search-input"]').type('quick search');

    // Verify API call is made again
    cy.wait('@searchRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Type a third query and wait for 300ms
    cy.get('[data-testid="search-input"]').type('quick search');
    cy.wait(300);

    // Verify API call is not made during the 300ms delay
    cy.wait('@searchRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify search results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-results"]').should('contain', 'quick search');
  });

  it('should handle backspace and clear input without triggering search', () => {
    // Setup: intercept the search API call
    cy.intercept('GET', '/api/search*').as('searchRequest');

    // Get the search input element
    cy.get('[data-testid="search-input"]').should('be.visible');

    // Type a query
    cy.get('[data-testid="search-input"]').type('test search');

    // Verify API call is made
    cy.wait('@searchRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Clear the input
    cy.get('[data-testid="search-input"]').clear();

    // Verify API call is not made after clearing
    cy.wait('@searchRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Type a new query
    cy.get('[data-testid="search-input"]').type('test search');

    // Verify API call is made
    cy.wait('@searchRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify search results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-results"]').should('contain', 'test search');
  });
});
